3	import java.util.Map;
4	import java.util.Optional;
5	
6	/**
7	 * Shared telephone handling: converts a raw number to its canonical E.164 form so numbers
8	 * written with different separators (or an explicit country code) compare equal. Used both
9	 * to normalize a create request before it is persisted and to compare it against existing
10	 * owners' stored numbers.
11	 */
12	public final class Telephones {
13	
14	    /** Country code assumed when the input carries no explicit '+' prefix (Australia). */
15	    private static final String DEFAULT_COUNTRY_CODE = "61";
16	
17	    /**
18	     * Required national-number length (the digits after the country code) for each country
19	     * code we recognise: '+61' (Australia) takes 9, '+1' (NANP) takes 10. A number whose
20	     * country code is not listed is accepted on the generic 8-15 digit range alone.
21	     */
22	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS = Map.of("61", 9, "1", 10);
23	
24	    private Telephones() {
25	    }
26	
27	    /**
28	     * Converts {@code telephone} to E.164 (a leading '+' followed by 8 to 15 digits).
29	     *
30	     * <p>Spaces, dashes and brackets are stripped. When the number keeps a leading '+' its
31	     * country code is preserved; otherwise {@code +61} is assumed and a single leading '0'
32	     * is dropped from the national digits. Returns empty when the result cannot form valid
33	     * E.164 (non-digits remain, the digit count is out of range, or the national number is
34	     * the wrong length for a recognised country code).
35	     */
36	    static Optional<String> toE164(String telephone) {
37	        if (telephone == null) {
38	            return Optional.empty();
39	        }
40	        String cleaned = telephone.replaceAll("[\\s()\\-]", "");
41	        String digits;
42	        if (cleaned.startsWith("+")) {
43	            digits = cleaned.substring(1);
44	        }
45	        else {
46	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
47	            digits = DEFAULT_COUNTRY_CODE + national;
48	        }
49	        if (!digits.matches("[0-9]{8,15}") || !hasValidNationalNumberLength(digits)) {
50	            return Optional.empty();
51	        }
52	        return Optional.of("+" + digits);
53	    }
54	
55	    /**
56	     * Formats a stored E.164 number for humans as the country code, a space, then the national
57	     * digits grouped in threes, e.g. {@code +61412345678} becomes {@code +61 412 345 678}.
58	     * Returns the input unchanged when it is not in E.164 form (null, or not a '+' followed by
59	     * digits); its country code splits off the recognised prefix, falling back to grouping all
60	     * digits when the code is not one we know.
61	     */
62	    public static String toDisplay(String e164) {
63	        if (e164 == null || !e164.matches("\\+[0-9]+")) {
64	            return e164;
65	        }
66	        String digits = e164.substring(1);
67	        String countryCode = longestCountryCode(digits);
68	        if (countryCode == null) {
69	            return "+" + groupInThrees(digits);
70	        }
71	        return "+" + countryCode + " " + groupInThrees(digits.substring(countryCode.length()));
72	    }
73	
74	    /** Groups {@code digits} into space-separated runs of three, counting from the left. */
75	    private static String groupInThrees(String digits) {
76	        StringBuilder grouped = new StringBuilder();
77	        for (int i = 0; i < digits.length(); i++) {
78	            if (i > 0 && i % 3 == 0) {
79	                grouped.append(' ');
80	            }
81	            grouped.append(digits.charAt(i));
82	        }
83	        return grouped.toString();
84	    }
85	
86	    /**
87	     * Checks the national-number length of {@code digits} (the E.164 digits without the '+')
88	     * against its country code, using the longest recognised code the number starts with.
89	     * Unrecognised country codes pass, having already cleared the generic 8-15 digit range.
90	     */
91	    private static boolean hasValidNationalNumberLength(String digits) {
92	        String countryCode = longestCountryCode(digits);
93	        if (countryCode == null) {
94	            return true;
95	        }
96	        return digits.length() - countryCode.length() == NATIONAL_NUMBER_LENGTHS.get(countryCode);
97	    }
98	
99	    /**
100	     * The longest recognised country code (a key of {@link #NATIONAL_NUMBER_LENGTHS}) that
101	     * {@code digits} starts with, or {@code null} when it starts with none of them.
102	     */
103	    private static String longestCountryCode(String digits) {
104	        String countryCode = null;
105	        for (String candidate : NATIONAL_NUMBER_LENGTHS.keySet()) {
106	            if (digits.startsWith(candidate)
107	                    && (countryCode == null || candidate.length() > countryCode.length())) {
108	                countryCode = candidate;
109	            }
110	        }
111	        return countryCode;
112	    }
113	}
114

